begin
             if at(15,31) then
             if wantenter('IMPERIUM MINOR') then begin
                with party do begin
                   map := 22; xaxis := 25; yaxis := 45;
                end;
                load;
             end;
             if at(34,14) then
             if wantenter('EVIL CONCENTRATION') then begin
                if party.etc[44] and bit1 = 0 then begin
                   enemynumber := 7;
                   for i := 1 to enemynumber do joinenemy(i,54);
                   joinenemy(random(5)+2,69);
                   displayenemies(TRUE);
                   Print(13,' 나는 EVIL CONCENTRATION 성의 입구를 지키는');
                   Print(13,'임무를 맡고 있는 Frost Dragon이다.  내가 지');
                   Print(13,'키고 있는한  너희들은 한 발자국도  들여놓지');
                   Print(13,'않을것이다.');
                   PressAnyKey;
                   battlemode(FALSE);
                   if party.etc[6] > 0 then exit;
                   party.etc[44] := party.etc[44] or bit1;
                end;
                with party do begin
                   map := 23; xaxis := 25; yaxis := 45;
                end;
                load;
             end;
          end

begin
              if y <= 6 then begin
                 if wantenter('SWAMP KEEP') then begin
                    with party do begin
                       map := 21; xaxis := 25; yaxis := 20;
                    end;
                    load;
                 end;
              end
              else begin
                 if wantenter('LAST SHELTER') then begin
                    with party do begin
                       map := 24; xaxis := 25; yaxis := 45;
                    end;
                    load;
                    if party.etc[43] and bit4 > 0 then map[33,10] := 47;
                 end;
              end;
           end

begin
              Clear;
              if y = 46 then begin
                 if wantexit then begin
                    if party.etc[43] and bit3 = 0 then begin
                       enemynumber := 7;
                       j := random(5) + 42;
                       if j = 42 then j := 35;
                       for i := 1 to 6 do joinenemy(i,j);
                       joinenemy(7,66);
                       displayenemies(TRUE);
                       Print(13,player[1].name+', 나의 힘을 보여주겠다.');
                       PressAnyKey;
                       battlemode(FALSE);
                       if enemy[7].dead then party.etc[43] := party.etc[43] or bit3;
                    end;
                    with party do begin
                       xaxis := 15; yaxis := 32; map := 5;
                    end;
                    load; scroll(TRUE);
                 end
                 else begin
                    dec(y); scroll(TRUE);
                 end;
              end
              else if on(25,18) then begin
                 if party.etc[43] and bit2 = 0 then begin
                    enemynumber := 5;
                    for i := 1 to 5 do joinenemy(i,60);
                    joinenemy(random(5)+1,63);
                    displayenemies(TRUE);
                    Print(13,' 나는 이 요새의 Wraith를 조종하는 죽음의 기');
                    Print(13,'사 Death Knight이다. 나에게 도전하다니 가소');
                    Print(13,'로운 것들. 으하하....');
                    PressAnyKey;
                    battlemode(FALSE);
                    if party.etc[6] = 255 then exit;
                    if party.etc[6] = 0 then party.etc[43] := party.etc[43] or bit2;
                 end;
              end
              else if (y=25) and (x in [24..26]) then begin
                 if party.etc[43] and bit1 = 0 then begin
                    enemynumber := 5;
                    joinenemy(1,61);
                    joinenemy(2,58);
                    joinenemy(3,56);
                    joinenemy(4,55);
                    joinenemy(5,60);
                    displayenemies(TRUE);
                    battlemode(TRUE);
                    if party.etc[6] = 255 then exit;
                    if party.etc[6] = 0 then party.etc[43] := party.etc[43] or bit1;
                 end;
              end
              else begin
                 if party.etc[43] and bit2 = 0 then begin
                    enemynumber := 5;
                    for i := 1 to enemynumber do joinenemy(i,60);
                    displayenemies(TRUE);
                    battlemode(FALSE);
                    map[x,y] := 40;
                 end;
              end;
           end
